INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000001', '特殊疑问句（W-Frage）', '特殊疑问句以疑问词开头：疑问词占第一位，变位动词占第二位，句末用问号。常用疑问词有 Wer? Was? Wo? Woher? Wie? Wann? 回答时不用 ja/nein，直接给出信息。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-1-001', 1, 1);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000001', '22222222-0000-0000-0000-000000000001', 'Wer bist du? Woher kommt Frau Tanaka?', '你是谁？田中女士来自哪里？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000002', '陈述句（Aussagesatz）', '陈述句中变位动词固定占第二位，句末用句号。第一位可以是主语，也可以是时间、地点等其他成分；第一位不是主语时，主语紧跟在动词之后。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-1-002', 1, 1);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000002', '22222222-0000-0000-0000-000000000002', 'Ich heiße Niklas. Sie kommt aus Japan.', '我叫尼克拉斯。她来自日本。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000003', '动词现在时变位与人称代词', '规则动词现在时由词干加人称词尾构成：ich -e, du -st, er/es/sie -t, wir -en, ihr -t, sie/Sie -en。sein 不规则：ich bin, du bist, er ist, wir sind, ihr seid, sie sind。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-1-003', 1, 1);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000003', '22222222-0000-0000-0000-000000000003', 'Ich komme aus Spanien. Du wohnst in Frankfurt.', '我来自西班牙。你住在法兰克福。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000004', '语篇中的人称代词', '为避免重复名词，用第三人称代词指代前文的人或物：阳性用 er，中性用 es，阴性用 sie。代词作主语时，动词形式与第三人称单数一致。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-1-004', 1, 1);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000004', '22222222-0000-0000-0000-000000000004', 'Das ist Frau Lang. Sie kommt aus Deutschland.', '这是朗女士。她来自德国。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000005', '不规则动词现在时变位', '部分强变化动词在 du 和 er/es/sie 时词干元音改变：a→ä（fahren: du fährst）、e→i（sprechen: du sprichst）、e→ie（lesen: du liest）。nehmen 特殊：du nimmst, er nimmt。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-2-001', 1, 2);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000005', '22222222-0000-0000-0000-000000000005', 'Er spricht Deutsch und Englisch. Wann fährst du nach Berlin?', '他会说德语和英语。你什么时候去柏林？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000006', '一般疑问句（Ja-/Nein-Frage）', '一般疑问句没有疑问词，变位动词提到句首第一位，主语紧随其后，句末用问号。回答用 Ja 或 Nein；若问句本身含否定，肯定的回答要用 Doch。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-2-002', 1, 2);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000006', '22222222-0000-0000-0000-000000000006', 'Gehen wir ins Kino? – Ja, gern. Kommst du nicht mit? – Doch.', '我们去看电影吗？——好啊。你不一起来吗？——不，我来。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000007', '定冠词 der, das, die', '德语名词分阳性、中性和阴性，定冠词分别是 der、das、die；复数一律用 die。定冠词用于说话双方已知或上文已提到的人或事物。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-2-003', 1, 2);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000007', '22222222-0000-0000-0000-000000000007', 'Das ist der Hafen, das Hotel und die Brücke.', '这是港口、旅馆和桥。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000008', '名词的单数与复数', '名词复数有多种词尾：-(e)n（die Stunde – die Stunden）、-e（der Tag – die Tage）、-er（das Buch – die Bücher）、-s（das Auto – die Autos），有的复数不加词尾。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-2-004', 1, 2);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000008', '22222222-0000-0000-0000-000000000008', 'Das ist ein Buch. Das sind zwei Bücher.', '这是一本书。这是两本书。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000009', '动词 haben 和 sein', 'haben 和 sein 是最重要的两个不规则动词。haben：ich habe, du hast, er hat, wir haben, ihr habt, sie haben。sein：ich bin, du bist, er ist, wir sind, ihr seid, sie sind。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-2-005', 1, 2);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000009', '22222222-0000-0000-0000-000000000009', 'Ich habe heute Zeit. Hast du auch Zeit?', '我今天有时间。你也有时间吗？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000010', '不定冠词 ein/eine', '不定冠词用于首次提到、尚不明确的人或事物：阳性和中性用 ein，阴性用 eine，复数不用冠词。它相当于汉语的“一个”，但复数形式没有对应词。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-3-001', 1, 3);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000010', '22222222-0000-0000-0000-000000000010', 'Das ist ein Hafen. Das ist eine Brücke.', '这是一个港口。这是一座桥。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000011', '否定冠词 kein/keine', '否定带不定冠词或不带冠词的名词时用 kein：阳性和中性用 kein，阴性和复数用 keine。否定动词或整个句子时则用 nicht。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-3-002', 1, 3);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000011', '22222222-0000-0000-0000-000000000011', 'Das ist kein Bahnhof. Das sind keine Autos.', '这不是火车站。这些不是汽车。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000012', '命令式（Sie 形式）', '对 Sie 的祈使句：动词不定式加 Sie，动词占句首第一位，句末用感叹号。可分动词的前缀留在句末。sein 的特殊形式是 Seien Sie ...!', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-3-003', 1, 3);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000012', '22222222-0000-0000-0000-000000000012', 'Gehen Sie links! Fahren Sie rechts!', '您往左走。您往右开。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000013', '形容词作表语（sein + Adjektiv）', '形容词作表语时不变格，直接放在 sein 之后，用来描述人或事物：Das Haus ist groß. 主语和形容词之间不加冠词或其他词。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-3-004', 1, 3);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000013', '22222222-0000-0000-0000-000000000013', 'Der Turm ist 112 Meter hoch. Der Hafen ist groß.', '这座塔高 112 米。这个港口很大。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000014', '第四格（Akkusativ）', '第四格用作动词的直接宾语。只有阳性冠词发生变化：der→den, ein→einen, kein→keinen, mein→meinen；中性、阴性和复数的冠词与第一格相同。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-4-001', 1, 4);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000014', '22222222-0000-0000-0000-000000000014', 'Ich kaufe den Käse. Ich habe einen Salat.', '我买这奶酪。我有一份沙拉。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000015', '支配第四格的动词', '许多动词要求第四格宾语，如 brauchen, haben, machen, kochen, essen, kaufen, nehmen, mögen, möchten。记住动词时应连同所支配的格一起记。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-4-002', 1, 4);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000015', '22222222-0000-0000-0000-000000000015', 'Ich brauche eine Gurke. Wir kaufen die Getränke.', '我需要一根黄瓜。我们买饮料。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000016', '动词 mögen 和 möchten', 'möchten 表示“想要”，mögen 表示“喜欢”，两者都不规则。变位：ich mag/möchte, du magst/möchtest, er mag/möchte, wir mögen/möchten, ihr mögt/möchtet, sie mögen/möchten。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-4-003', 1, 4);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000016', '22222222-0000-0000-0000-000000000016', 'Ich mag keinen Käse. Ich möchte ein Würstchen.', '我不喜欢奶酪。我想要一根香肠。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000017', '句子成分的位置（陈述句语序复习）', '复习并巩固 L1 的规则：陈述句中变位动词占第二位。主语可以在动词前，也可以在动词后：把时间或地点状语提到句首时，主语就移到动词后面，动词位置始终不变。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-4-004', 1, 4);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000017', '22222222-0000-0000-0000-000000000017', 'Lina isst morgens Müsli. Morgens isst Lina Müsli.', '莉娜早上吃麦片。早上莉娜吃麦片。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000018', '时间状语 am, um, von ... bis', '星期和一天中的时段用 am：am Montag, am Vormittag；钟点用 um：um 14:45 Uhr, um Viertel vor drei；时间段用 von ... bis：von Montag bis Samstag。提问用 Wann? 或 Wie lange?', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-5-001', 1, 5);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000018', '22222222-0000-0000-0000-000000000018', 'Am Montag arbeite ich von neun bis halb zwei. Um sieben frühstücke ich.', '周一我从九点工作到一点半。我七点吃早饭。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000019', '物主冠词（第一格与第四格）', '物主冠词表示所属：mein, dein, sein, ihr（她的）, unser, euer, ihr（他们的）, Ihr（您的）。阳性和中性第一格不加词尾（mein Vater, mein Kind），阴性和复数加 -e（meine Mutter, meine Eltern）；第四格阳性为 meinen。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-5-002', 1, 5);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000019', '22222222-0000-0000-0000-000000000019', 'Mein Vater wohnt in Köln. Ich rufe meinen Vater an.', '我父亲住在科隆。我给我父亲打电话。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000020', '情态动词 müssen, können, wollen', '情态动词 müssen（必须）、können（能够）、wollen（想要）变位特殊：ich 和 er/es/sie 的形式不加词尾（muss, kann, will），其他人称加 -st/-t/-en，后面跟动词不定式。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-5-003', 1, 5);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000020', '22222222-0000-0000-0000-000000000020', 'Ich muss heute arbeiten. Kannst du mir helfen?', '我今天必须工作。你能帮我吗？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000021', '情态动词的句子框架（Satzklammer）', '情态动词作变位动词占第二位，句末的不定式与之构成“句子框架”。一般疑问句中情态动词提到第一位，不定式仍然留在句末，两部分把句子夹在中间。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-5-004', 1, 5);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000021', '22222222-0000-0000-0000-000000000021', 'Ich kann heute nicht kommen. Willst du ins Kino gehen?', '我今天不能来。你想去看电影吗？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000022', '日期表达（am + 序数词）', '说日期用 am 加序数词：am 5. Mai / am fünften Mai。1 到 19 的序数词由基数词加 -te 构成（vierte, fünfte ... neunzehnte），但 erste、dritte、siebte、achte 不规则，需要单独记；20 起加 -ste（zwanzigste ...）。提问用 Wann?', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-6-001', 1, 6);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000022', '22222222-0000-0000-0000-000000000022', 'Am ersten Mai habe ich frei. Mein Geburtstag ist am zwölften Mai.', '五月一日我休息。我的生日在五月十二日。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000023', '可分动词（trennbare Verben）', '可分动词由前缀和动词组成，如 ab|holen, an|fangen, an|rufen, ein|laden, mit|bringen。现在时中前缀与动词分离并移到句末，不定式中用 | 标出可分处。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-6-002', 1, 6);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000023', '22222222-0000-0000-0000-000000000023', 'Sie lädt die Freunde ein. Wir holen Sofia ab.', '她邀请朋友们。我们去接索菲亚。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000024', '人称代词第四格', '人称代词的第四格形式：mich, dich, ihn, es, sie, uns, euch, sie, Sie。它们作动词的直接宾语，通常放在名词宾语之前。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-6-003', 1, 6);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000024', '22222222-0000-0000-0000-000000000024', 'Ich lade dich ein. Holst du mich ab?', '我邀请你。你来接我吗？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000025', '介词 für + 第四格', '介词 für 后面总是跟第四格：für mich, für dich, für ihn, für den Hund, für eine Freundin。询问“给谁”用 Für wen ...?', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-6-004', 1, 6);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000025', '22222222-0000-0000-0000-000000000025', 'Für wen ist das Wasser? – Das Wasser ist für den Hund.', '这水是给谁的？——这水是给狗的。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000026', 'haben 和 sein 的过去时', 'haben 和 sein 常用过去时（Präteritum）：ich war/hatte, du warst/hattest, er war/hatte, wir waren/hatten, ihr wart/hattet, sie waren/hatten。过去时用来叙述过去的事情。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-6-005', 1, 6);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000026', '22222222-0000-0000-0000-000000000026', 'Ich war zu Hause. Wir hatten viel Spaß.', '我当时在家。我们玩得很开心。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000027', '并列连词 und, oder, aber', 'und（和）、oder（或者）、aber（但是）连接两个主句，位于两个句子之间，后面语序不变。若两个句子的主语相同，第二个主语可以省略。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-7-001', 1, 7);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000027', '22222222-0000-0000-0000-000000000027', 'Ich bin in Köln und mache ein Praktikum. Die Firma ist klein, aber sie hat viele Kunden.', '我在科隆，在实习。这家公司很小，但客户很多。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000028', '第三格冠词（Dativ）', '第三格中冠词变为：阳性 der→dem、中性 das→dem、阴性 die→der、复数 die→den。不定冠词为 einem/einem/einer/-，否定冠词为 keinem/keinem/keiner/keinen。名词的第三格复数通常加 -n（die Kinder→den Kindern），但复数本身以 -n 或 -s 结尾时不加（die Frauen→den Frauen，die Autos→den Autos）。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-7-002', 1, 7);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000028', '22222222-0000-0000-0000-000000000028', 'Ich helfe dem Mann. Ich helfe der Frau.', '我帮助这位男士。我帮助这位女士。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000029', '介词 mit + 第三格', '介词 mit 后面总是跟第三格：mit mir, mit dir, mit ihm, mit dem Taxi, mit einer Freundin, mit den Mitarbeitern。询问“和谁”用 Mit wem ...?', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-7-003', 1, 7);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000029', '22222222-0000-0000-0000-000000000029', 'Mit wem fährt Laura? – Sie fährt mit einem Freund und einer Freundin.', '劳拉和谁一起去？——她和一个男朋友、一个女朋友一起去。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000030', '地点介词与第三格', '表示"在哪里"（Wo?）用第三格介词 in, bei, an, auf 等；表示"去哪里"（Wohin?）用 zu（人或人的场所），去城市、国家或回家用 nach（nach Berlin, nach Hause）；表示"从哪里来"（Woher?）用 aus, von。常见缩合：zum, zur, beim, vom, im。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-7-004', 1, 7);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000030', '22222222-0000-0000-0000-000000000030', 'Sie geht zum Chef. Sie ist beim Chef.', '她去老板那里。她在老板那里。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000031', '命令式：du、ihr、Sie', '命令式有三种形式：du 形式用动词词干（Mach! Lauf!），词干以 -d、-t、-ig 结尾时加 -e（Arbeite!）；换元音动词（e→i/ie）在命令式中保留换音（Lies! Sprich!），a→ä 类不换（Fahr!）。ihr 形式用动词的 ihr 形式（Macht! Lauft!），Sie 形式为不定式加 Sie（Machen Sie!）。sein 特殊：Sei! Seid! Seien Sie!', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-8-001', 1, 8);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000031', '22222222-0000-0000-0000-000000000031', 'Mach Sport! Sei sportlich!', '做运动！要爱运动！');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000032', '命令句的结构', '命令句中变位动词占第一位，句末用感叹号。可分动词的前缀移到句末。主语 du 和 ihr 通常省略，Sie 必须保留。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-8-002', 1, 8);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000032', '22222222-0000-0000-0000-000000000032', 'Geh früh ins Bett! Trinken Sie viel Wasser!', '早点睡！请您多喝水！');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000033', '情态动词 sollen, müssen, dürfen', 'sollen 表示建议或转述要求，müssen 表示必须，dürfen 表示允许，nicht dürfen 表示禁止。变位：ich soll/muss/darf, du sollst/musst/darfst, er soll/muss/darf。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-8-003', 1, 8);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000033', '22222222-0000-0000-0000-000000000033', 'Du sollst mehr schlafen. Sie müssen im Bett bleiben.', '你应该多睡觉。您必须卧床。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000034', '许可、要求与禁止的表达', '表达许可用 dürfen，表达要求或命令用 müssen，表达禁止用 nicht dürfen：Sie dürfen duschen. Du musst zu Hause bleiben. 常用句型还有 Es ist verboten.', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-8-004', 1, 8);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000034', '22222222-0000-0000-0000-000000000034', 'Du darfst viel Tee trinken. Sie dürfen das nicht machen.', '你可以多喝茶。您不可以这样做。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000035', '转述要求（sollen）', '转述别人的要求或医嘱时用 sollen：Der Arzt sagt, ich soll viel trinken. 主句用 sagen 等动词，从句里用 sollen 表达“应该做某事”，也可以直接说 Ich soll das Bein wenig bewegen.', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-8-005', 1, 8);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000035', '22222222-0000-0000-0000-000000000035', 'Der Arzt sagt, ich soll viel trinken. Ich soll das Bein wenig bewegen.', '医生说我要多喝水。我应该少动这条腿。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000036', '形容词表语的程度与否定', '表语形容词常与 nicht、sehr、zu 连用，表示否定或程度：Die Wohnung ist nicht billig / sehr teuer / zu teuer。形容词本身不变格，通常跟在 sein 之后（也可跟在 werden、bleiben 之后）。', '初级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-9-001', 1, 9);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000036', '22222222-0000-0000-0000-000000000036', 'Die Wohnung ist sehr teuer. Das Zimmer ist zu klein.', '这套房子很贵。这个房间太小。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000037', '介词 in + 第四格', '表示“进入某处”（Wohin?）时，介词 in 后面的冠词用第四格：in die Stadt, in den Park, in ein Haus, in einen Supermarkt。表示“在某处”（Wo?）时则用第三格。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-9-002', 1, 9);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000037', '22222222-0000-0000-0000-000000000037', 'Ich gehe in die Stadt. Wir gehen in den Park.', '我进城去。我们去公园。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000038', '方位介词（Wechselpräpositionen）', '方位介词 an, auf, hinter, in, neben, über, unter, vor, zwischen 表示位置（Wo?）时用第三格，表示方向（Wohin?）时用第四格：Das Bild hängt an der Wand / Ich hänge es an die Wand.', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-9-003', 1, 9);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000038', '22222222-0000-0000-0000-000000000038', 'Das Bild hängt an der Wand. Die Lampe steht neben dem Bett.', '画挂在墙上。台灯放在床边。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000039', '表达喜欢与不喜欢（finden + 形容词）', '评价住处或物品时可用 finden + 第四格 + 形容词：Ich finde die Wohnung zu klein. Ich finde die Lampe hässlich. 也可以用 sein + doch + 形容词表示赞同：Die Lampe ist doch toll.', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-9-004', 1, 9);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000039', '22222222-0000-0000-0000-000000000039', 'Ich finde die Wohnung zu klein. Die Lampe ist doch toll.', '我觉得这套房子太小。这盏灯挺好看的。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000040', '现在完成时的句子框架（Perfekt）', '现在完成时由助动词 haben 或 sein 的现在时加过去分词构成，形成句子框架：助动词占第二位，过去分词在句末，中间可以放其他成分。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-10-001', 1, 10);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000040', '22222222-0000-0000-0000-000000000040', 'Ich habe gestern viel gearbeitet. Sie ist nach Wien gefahren.', '我昨天干了很多活。她去了维也纳。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000041', '过去分词（Partizip II）', '规则动词为 ge- + 词干 + -t（machen→gemacht）。不规则动词为 ge- + 变化后的词干 + -en（fahren→gefahren, gehen→gegangen）。特殊：denken→gedacht, wissen→gewusst。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-10-002', 1, 10);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000041', '22222222-0000-0000-0000-000000000041', 'Ich habe die Hausaufgaben gemacht. Sie ist nach Berlin gefahren.', '我做完了作业。她去了柏林。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000042', '-ieren 结尾动词的过去分词', '以 -ieren 结尾的动词构成过去分词时不加 ge-，只加 -t：studieren→studiert, telefonieren→telefoniert, passieren→passiert。这类动词的重音在 -ieren 上。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-10-003', 1, 10);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000042', '22222222-0000-0000-0000-000000000042', 'Ich habe in Berlin studiert. Wir haben lange telefoniert.', '我在柏林上过大学。我们通了很久电话。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000043', '现在完成时的助动词 haben 与 sein', '大多数动词用 haben 构成现在完成时；表示位置移动或状态改变的动词用 sein，如 fahren, gehen, kommen, ankommen, aufstehen。bleiben 和 passieren 也要求用 sein。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-10-004', 1, 10);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000043', '22222222-0000-0000-0000-000000000043', 'Wir haben viel gearbeitet. Ich bin um sechs Uhr aufgestanden.', '我们干了很多活。我六点起床了。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000044', '完成时的 gewesen 与 gehabt', 'sein 和 haben 也有完成时形式 ich bin gewesen 和 ich habe gehabt，但它们很少使用；表达过去的事情时通常直接用过去时 ich war 和 ich hatte。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-10-005', 1, 10);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000044', '22222222-0000-0000-0000-000000000044', 'Ich war gestern in Berlin. Wir hatten viel Zeit.', '我昨天在柏林。我们那时有很多时间。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000045', '疑问冠词 Welcher? Welches? Welche?', '询问“哪一个”用 welcher/welches/welche，词尾变化与定冠词一致：Welcher Mantel? Welches Kleid? Welche Jacke? 第四格阳性为 welchen，第三格为 welchem/welcher/welchen。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-11-001', 1, 11);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000045', '22222222-0000-0000-0000-000000000045', 'Welchen Mantel nimmst du? Welche Jacke gefällt dir?', '你拿哪件大衣？你喜欢哪件夹克？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000046', '指示冠词 dieser, dieses, diese', '指示冠词 dieser/dieses/diese 表示“这个”，词尾变化与定冠词相同：dieser Mantel, dieses Kleid, diese Jacke, diese Schuhe。第四格阳性为 diesen，第三格为 diesem/dieser/diesen。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-11-002', 1, 11);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000046', '22222222-0000-0000-0000-000000000046', 'Dieser Mantel ist zu teuer. Ich nehme diese Jacke.', '这件大衣太贵了。我买这件夹克。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000047', '带前缀动词的过去分词', '可分动词的 -ge- 放在前缀与词干之间：an|kommen→ist angekommen, an|ziehen→hat angezogen。不可分动词（前缀 be-, emp-, ent-, er-, ge-, ver-, zer-）不加 -ge-。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-11-003', 1, 11);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000047', '22222222-0000-0000-0000-000000000047', 'Sie ist angekommen. Er hat den Pullover umgetauscht.', '她到了。他把毛衣换了。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000048', '人称代词第三格', '人称代词的第三格形式：mir, dir, ihm, ihm, ihr, uns, euch, ihnen, Ihnen。第三格代词作动词的间接宾语，通常放在第四格宾语之前。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-11-004', 1, 11);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000048', '22222222-0000-0000-0000-000000000048', 'Kann ich Ihnen helfen? Die Jacke gefällt mir.', '我能帮您吗？我喜欢这件夹克。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000049', '支配第三格的动词', '部分动词要求第三格宾语：gefallen（讨……喜欢）、helfen（帮助）、passen（合身）、stehen（合适）、gehören、danken。句型为 etwas gefällt jemandem / jemandem helfen。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-11-005', 1, 11);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000049', '22222222-0000-0000-0000-000000000049', 'Der Pullover gefällt mir sehr gut. Die Jacke passt ihr nicht.', '这件毛衣我很喜欢。这件夹克她穿不合身。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000050', '不定代词 man', '不定代词 man 泛指"人们"，只作主语，动词用第三人称单数形式。A1 阶段只需掌握它作主语（第一格）的用法；第四格和第三格分别用 einen、einem 代替。句子里的其他成分照常用第四格或第三格。', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-12-001', 1, 12);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000050', '22222222-0000-0000-0000-000000000050', 'Man kann in der Altstadt spazieren gehen. Man darf hier nicht parken.', '人们可以在老城里散步。这里不允许停车。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000051', '连词 denn', 'denn 表示原因，连接两个主句，位于第二位，后面语序不变（变位动词仍占该句第二位）。提问原因用 Warum?', '中级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-12-002', 1, 12);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000051', '22222222-0000-0000-0000-000000000051', 'Ich mag das Museum, denn die Kunst gefällt mir. Ich lerne Deutsch, denn ich arbeite in Berlin.', '我喜欢这家博物馆，因为我喜欢艺术。我学德语，因为我在柏林工作。');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000052', '疑问词 Wer? Wen? Wem? Was?', '疑问词有格的变化：问人第一格 Wer?、第四格 Wen?、第三格 Wem?；问事物用 Was?。此外还按意义分类：问地点 Wo?/Wohin?/Woher?，问时间 Wann?/Wie lange?，问方式 Wie?，问原因 Warum?', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-12-003', 1, 12);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000052', '22222222-0000-0000-0000-000000000052', 'Wer ist das? Wen hast du eingeladen?', '这是谁？你邀请了谁？');
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES ('22222222-0000-0000-0000-000000000053', '时间介词 + 第三格', '表示时间关系的介词支配第三格：ab dem Moment, am Montag, im August, nach dem Urlaub, seit einer Woche, vor der Reise。注意 an+dem=am、in+dem=im 的缩合形式。', '高级', 1, '2026-01-01T00:00:00.000Z', 'GP-1-12-004', 1, 12);
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES ('22222223-0000-0000-0000-000000000053', '22222222-0000-0000-0000-000000000053', 'Seit einer Woche bin ich hier. Nach dem Urlaub fahre ich nach Hause.', '我在这里已经一周了。假期后我回家。');
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id, error_word_index, error_options, source) VALUES ('33333333-0000-0000-0000-000000000001', '22222222-0000-0000-0000-000000000001', 'G1', '（怎样） heißt du? – Ich heiße Niklas.', 'Wie', '考查特殊疑问句疑问词的选择：疑问词占第一位，变位动词占第二位。', '初级', '2026-01-01T00:00:00.000Z', 'GQ-1-1-001', 'GP-1-1-001', NULL, NULL, '题库');
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id, error_word_index, error_options, source) VALUES ('33333333-0000-0000-0000-000000000002', '22222222-0000-0000-0000-000000000001', 'G1', '（谁） ist das? – Das ist Frau Lang.', 'Wer', '考查特殊疑问句疑问词的选择：疑问词占第一位，变位动词占第二位。', '初级', '2026-01-01T00:00:00.000Z', 'GQ-1-1-002', 'GP-1-1-001', NULL, NULL, '题库');
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id, error_word_index, error_options, source) VALUES ('33333333-0000-0000-0000-000000000003', '22222222-0000-0000-0000-000000000001', 'G1', '（从哪里） kommst du? – Ich komme aus China.', 'Woher', '考查特殊疑问句疑问词的选择：疑问词占第一位，变位动词占第二位。', '初级', '2026-01-01T00:00:00.000Z', 'GQ-1-1-003', 'GP-1-1-001', NULL, NULL, '题库');
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id, error_word_index, error_options, source) VALUES ('33333333-0000-0000-0000-000000000004', '22222222-0000-0000-0000-000000000001', 'G1', '（什么） ist das? – Das ist ein Buch.', 'Was', '考查特殊疑问句疑问词的选择：疑问词占第一位，变位动词占第二位。', '初级', '2026-01-01T00:00:00.000Z', 'GQ-1-1-004', 'GP-1-1-001', NULL, NULL, '题库');
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id, error_word_index, error_options, source) VALUES ('33333333-0000-0000-0000-000000000005', '22222222-0000-0000-0000-000000000001', 'G1', '（什么时候） kommt der Bus? – Um acht Uhr.', 'Wann', '考查特殊疑问句疑问词的选择：疑问词占第一位，变位动词占第二位。', '初级', '2026-01-01T00:00:00.000Z', 'GQ-1-1-005', 'GP-1-1-001', NULL, NULL, '题库');
